def check_sequence(x1, x2):
    """
    Checks if a sequence starting with (x1, x2) continues,
    and returns the length n found if it terminates.
    """
    if x1 <= 0 or x2 <= 0:
        return 1

    sequence = [x1, x2]
    max_length = 30 # Increased limit

    for i in range(1, max_length):
        x_current = sequence[-1]
        x_prev = sequence[-2]

        numerator = x_current**2 - x_prev
        denominator = x_prev + 1

        if denominator <= 0: # Should not happen for positive integers
            return len(sequence)

        if numerator % denominator != 0:
            return len(sequence)

        x_next = numerator // denominator

        if x_next <= 0:
            return len(sequence)

        sequence.append(x_next)

    return len(sequence) # Reached max_length

